def to_icons(apps, schema_editor):
    for model, field in ICON_FIELDS:
        Model = apps.get_model("portfolio", model)
        for obj in Model.objects.all():
            value = _MODIFIERS.sub("", getattr(obj, field) or "").strip()
            name = EMOJI_TO_ICON.get(value, value if value.isascii() and value else "circle-dot")
            setattr(obj, field, name)
            obj.save(update_fields=[field])
    for model, field, title_field, title, name in OVERRIDES:
        apps.get_model("portfolio", model).objects.filter(**{title_field: title}).update(**{field: name})
    for model, field in HEADING_FIELDS:
        Model = apps.get_model("portfolio", model)
        for obj in Model.objects.all():
            value = getattr(obj, field) or ""
            stripped = _LEADING_EMOJI.sub("", value)
            if stripped != value:
                setattr(obj, field, stripped)
                obj.save(update_fields=[field])



